import json,html,collections,hashlib
from pathlib import Path
repo=Path(__file__).resolve().parents[1]
c=json.load(open(repo/'scripts/author-reviews.json'));manifest=json.load(open(repo/'scripts/manifest.json'));rows=[]
for m in manifest:
 if m['status']=='removed':continue
 rec=c['scripts'][m['id']];p=c['publications'].get(rec['publication'],{});s=c['sources'].get(m['file'],{})
 rows.append(dict(id=m['id'],name=m['name'],author=p.get('author') or 'Unverified author',url=p.get('url'),status=m['status'],reviewed=bool(p.get('reviewedAt')) and p.get('version')==p.get('reviewVersion') and p.get('updatedAt')==p.get('reviewUpdatedAt'),blocker=p.get('reviewBlocker',{}).get('blocker'),findings=p.get('reconciliation',{}).get('findings',[]),retrieved=bool(p.get('retrievedAt')),role=p.get('role') or s.get('type'),idea=p.get('summary') or s.get('idea'),requirements=p.get('requirements'),notes=rec['integrationNotes'],entryCount=len(s.get('entries',[])),sourceDate=s.get('reviewedAt')))
keys={c['scripts'][r['id']]['publication']for r in rows};keys.discard(None);verified=sum(bool(p.get('reviewedAt')) and p.get('version')==p.get('reviewVersion') and p.get('updatedAt')==p.get('reviewUpdatedAt') for k in keys for p in [c['publications'][k]]);fetched=sum(bool(c['publications'][k]['retrievedAt'])for k in keys)
matched=sum(bool(c['sources'].get(m['file'])) and hashlib.sha256((repo/'scripts/pine'/m['file']).read_bytes()).hexdigest()==c['sources'][m['file']]['sha256'] for m in manifest if m['status']!='removed')
result=dict(at=c['generatedAt'],retainedEntries=len(rows),publications=len(keys),authorReviews=verified,publicationPagesRetrieved=fetched,sourceContractsMatched=matched,pendingAuthorReview=len(keys)-verified,unavailablePages=len(keys)-fetched,blockedReviews=sum(bool(c['publications'][k].get('reviewBlocker')) for k in keys),reconciliationFindings=sum(len(c['publications'][k].get('reconciliation',{}).get('findings',[])) for k in keys))
(repo/'docs/research/library-author-reconciliation-2026-11-14/retained-coverage.json').write_text(json.dumps(result,indent=2)+'\n')
body='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>VN EDGE · Author reconciliation</title><style>
:root{color-scheme:dark}body{margin:0;background:#0c1320;color:#dae4f3;font:15px/1.5 system-ui}main{max-width:1200px;margin:40px auto;padding:0 24px}h1{font-size:34px;letter-spacing:-1px}h2{font-size:21px;margin-top:30px}a{color:#70b7ff}p{max-width:960px}.muted{color:#9cadc5}.cards{display:flex;gap:12px;flex-wrap:wrap}.card{background:#172337;border:1px solid #2a3c55;padding:16px;min-width:180px}.big{font-size:30px;display:block}input,select,button{font:inherit;background:#172337;color:inherit;border:1px solid #3a526e;padding:10px;margin:4px}input{min-width:300px}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:12px;border-bottom:1px solid #28384d;vertical-align:top}td:first-child{min-width:230px}summary{cursor:pointer}.note{border-left:3px solid #e3b76e;padding:10px 18px;background:#192333}button{cursor:pointer}small{color:#9cadc5}@media(max-width:700px){main{padding:0 12px}.table{overflow:auto}input{min-width:200px}}</style><main>
<div class="muted">VN EDGE · Engineering review · 14 November 2026 IST</div><h1>Author intent, source conditions and bot execution</h1>
<p>Each retained script is linked to its source contract, author-review receipt and unresolved integration work. Reader corrections are tested under separate experimental identities. This index is research, not trading approval or proof of profitability.</p>
<div class="cards">'''+''.join(f'<div class="card"><span class="big">{n:,}</span>{label}</div>'for n,label in [(len(rows),'retained library entries'),(matched,'matching source contracts'),(verified,'author publications reconciled'),(len(keys)-verified,'author reviews still pending')])+'''</div>
<p class="note"><strong>Coverage is not completion.</strong> Prior line-by-line source work was reused after hash checks; five newer source versions were reconciled separately. Previously completed Willy and BigBeluga reviews are retained. Additional parallel reviews are imported only with matching publication metadata and inspected-source hashes. Unavailable or contradictory publications remain explicitly blocked. For the whole retained library, '''+str(verified)+' of '+str(len(keys))+''' author publications are reconciled. Downloaded descriptions are labelled pending; unavailable pages are not treated as reviewed.</p>
<h2>Confirmed integration gaps</h2><ul>
<li><a href="https://www.tradingview.com/script/XuywwObg-RSI-Volume-Ladder/">RSI Volume Ladder</a>: the author adds up to three legs and recalculates basket brackets. The bot ignores same-direction adds. A native basket adapter must keep the aggregate $150 budget and risk limits; the current strategy is an adaptation.</li>
<li><a href="https://www.tradingview.com/script/wMcOiPoG-Absorption-Reversal-Delta-Trap/">Absorption Reversal</a>: the source spacing OR can bypass absorption. Lower-timeframe candle delta coverage is also unresolved. Its existing quarantine stays in place.</li>
<li><a href="https://www.tradingview.com/script/oM444F7G-Trend-Fair-Value-Gap-Delta-ChartPrime/">Trend FVG Delta</a>: the author describes discretionary rejection entries; the source draws zones and statistics, not a complete entry condition. Candle-position volume is a proxy.</li>
<li>ML RSI classifier and SuperTrend cluster consensus outputs must remain distinct from regime/member flips. The existing comparison variants supply that distinction; generic-reader history is not interchangeable.</li>
<li>Trend Impulse continuation, Kinetic's selected marker, Asia-only Killzones and Pivot's long-only reading are deliberate bot variants. Compare alternatives under separate identities.</li></ul>
<h2>What changes in the bot</h2><p>Library → select a script → <strong>Author intent and bot reading</strong> shows the publication author, reviewed source date, entry conditions, non-entry markers, stop/target/exit logic, timing caveats and current reading. A changed source hides obsolete conditions. Historical claims are scoped to the scanner and labelled as historical; refuted and unchecked claims are excluded. Review records do not change admission, positions, risk or evidence settings. Experimental shadow profiles are enabled separately by a tested operator script; they cannot supply promotion evidence.</p>
<h2>Tested shadow rollout</h2><p>The five available research slots are assigned to author-lifecycle SAVWAP, Synapse and Liquidity Trail, plus exact-direction Pivot Zones and Dynamic Bands signals on ETH 15m. Account enablement stays off. THMA, Liquidity Void, False Breakout, Adaptive Smart Money wick sweeps, Swing Failure, Zone Shift, Zero-Lag MA and Breaker Blocks retest corrections are source-tested and await research capacity. All plans retain $150 margin, the 3% stop ceiling and full research fees. The original 25 experiments and the 30-plan maximum are preserved.</p><p>Actual Pine runs on 2,000 historical ETH 15m bars produced entries for all seven reviewed profiles. Fourteen sampled prefix checks agreed without future bars. Three subsequent reading variants produced 22 failed-break entries, 170 qualified wick sweeps and 44 confirmed retests on the same 2,000-bar history; six more prefix checks agreed. Their legacy controls produced 22, 711 and 0 entries respectively. Zone Shift adds 43 confirmed diamonds (0 legacy events), using explicit label-style directions. Swing Failure now reads 18 qualified reversal shapes, excluding its identically named mitigation alerts (36 legacy events). A broader check across all 12 reviewed profiles reran 865 historical prefixes: every observed action bar after warm-up and regularly sampled quiet bars matched without later data. Breaker Blocks adds eight qualified retests after a hash-pinned, variant-only drawing compatibility correction; 22 further prefix checks agree. These totals describe interpretation changes, not improvement in returns. These check event semantics and timing; they do not establish profitability or complete historical depth replay.</p><p>The standalone backtest now uses the same configured reading, inputs and account policy as the screen. Native author stop amendments have an explicit after-close replay version; they cannot rewrite that candle’s earlier path. This candle approximation does not reproduce the live engine’s sub-bar stop acknowledgement timing. Other readers retain their earlier replay identity.</p><h2>Remaining work</h2><p>Review pending author explanations by family, reconcile every meaningful update against the pinned source, then reproduce each actionable mismatch with real source outputs. New lifecycle adapters need causal fill tests and separate shadow evidence. Preserve context-only roles; do not force every publication to generate entries.</p>
<p class="muted">Verified at '''+html.escape(c['generatedAt'])+f'''. Retained publication pages retrieved: {fetched:,}/{len(keys):,}; unavailable: {len(keys)-fetched}. Access failures remain recorded; no protected source was bypassed. Correctness tests do not establish improved net returns.</p>
<h2>Every retained script</h2><input id="search" aria-label="Search scripts" placeholder="Name, author or scanner ID"><select id="filter" aria-label="Review status"><option value="all">All scripts</option><option value="reviewed">Author reconciled</option><option value="pending">Author review pending</option><option value="unavailable">Page unavailable</option><option value="held">Correctness hold</option><option value="blocked">Author review blocked</option><option value="findings">Reconciliation findings</option></select><p id="count" class="muted"></p><div class="table"><table><thead><tr><th>Script / author</th><th>Author review</th><th>Conditions and integration</th></tr></thead><tbody id="rows"></tbody></table></div><button id="more">Show more</button>
<script>const rows='''+json.dumps(rows,ensure_ascii=False).replace('<','\\u003c')+''';let limit=40;const q=document.querySelector('#search'),f=document.querySelector('#filter');const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function render(){const query=q.value.toLowerCase(),v=f.value;const matches=rows.filter(r=>(r.name+' '+r.author+' '+r.id).toLowerCase().includes(query)&&(v==='all'||v==='reviewed'&&r.reviewed||v==='pending'&&!r.reviewed||v==='unavailable'&&!r.retrieved||v==='held'&&r.status==='incompatible'||v==='blocked'&&r.blocker||v==='findings'&&r.findings.length));document.querySelector('#count').textContent=matches.length+' entries · showing '+Math.min(limit,matches.length);document.querySelector('#rows').innerHTML=matches.slice(0,limit).map(r=>'<tr><td><a target="_blank" rel="noreferrer" href="'+esc(r.url||'#')+'">'+esc(r.name)+'</a><br><small>'+esc(r.author)+'<br>'+esc(r.id)+'</small></td><td>'+esc(r.reviewed?'Reconciled':r.blocker?'Blocked':r.retrieved?'Pending — page retrieved':'Unavailable')+'<br><small>'+esc(r.role)+'<br>Code study '+esc(r.sourceDate)+(r.status==='incompatible'?'<br>Correctness hold':'')+'</small></td><td>'+esc(r.idea)+'<br><small>'+r.entryCount+' source entry records</small><details><summary>Requirements and gaps</summary>'+esc([r.requirements,r.blocker,...r.notes,...r.findings.map(x=>x.marker+': '+x.evidence+' Required treatment: '+x.action)].filter(Boolean).join(' '))+'</details></td></tr>').join('');document.querySelector('#more').hidden=limit>=matches.length}q.oninput=f.onchange=()=>{limit=40;render()};document.querySelector('#more').onclick=()=>{limit+=40;render()};render();</script></main></html>'''
(repo/'docs/research/library-author-reconciliation-2026-11-14.html').write_text(body)
print(json.dumps(result,indent=2))
